#!/usr/bin/env python3
"""
universal_zip.py -- DEPRECATED, NOT FOR RELEASE (the plugins ship one strict zip per DWC line, see docs/DWC-LINES.md): merges a DWC 3.6 plugin zip and a DWC 3.7 plugin zip of the same plugin into ONE zip that installs and runs on both.

    python tools/universal_zip.py <Id>-dwc3.6.zip <Id>-dwc3.7.zip -o <Id>.zip

Design and evidence: docs-internal/UNIVERSAL-ZIP.md. In short:

  * DWC 3.6 loads exactly ONE js file of a plugin (the first dwcFiles entry whose name contains the plugin id and ends in .js,
    as a webpack chunk) and one css; DWC 3.7 injects EVERY listed .js as a classic <script> and every .css as a <link>.
  * So the merged zip holds ONE file, dwc/js/<Id>.<hash>.js, with both bundles inside and a run-time switch: window.DWC exists
    (3.7) -> run the IIFE bundle; otherwise self.webpackChunkduetwebcontrol exists (3.6) -> push the webpack chunk. The other
    bundle is never executed. css is not listed in dwcFiles (a 3.7 <link> would load the 3.6 css and the reverse): each side's
    css is embedded in the file and injected as a <style> by the branch that runs.
  * dwcVersion is "3": both DWC versions compare it as a PREFIX of their own version (checkVersion), so "3.6" would be refused
    by 3.7 and "3.7" by 3.6, while "3" passes on both.
  * sd/ and dsf/ (and any other payload) must be byte-identical in both inputs, else the merge is refused.

Used by build.py (--dwc universal) and usable on any pair of line zips, JS or Vue plugins alike.
"""
import argparse
import gzip
import hashlib
import json
import os
import re
import sys
import zipfile

UNIVERSAL_DWC_VERSION = "3"
# manifest keys that legitimately differ between the two lines (and are rebuilt here)
LINE_KEYS = ("dwcVersion", "dwcFiles", "rrfFiles")

HEAD = """/* {id} {version} -- universal bundle for DWC 3.6 and DWC 3.7, generated by tools/universal_zip.py, DO NOT edit.
   One file, two builds: the host decides at run time and only one of them executes. */
(function () {{
  "use strict";
  var PLUGIN_ID = {id_json};
  var CSS_36 = {css36};
  var CSS_37 = {css37};
  var host = typeof window !== "undefined" ? window : self;

  function injectCss(line, css) {{
    if (!css || typeof document === "undefined") return;
    var el = document.createElement("style");
    el.setAttribute("data-dwc-plugin", PLUGIN_ID);
    el.setAttribute("data-dwc-line", line);
    el.textContent = css;
    document.head.appendChild(el);
  }}

  // DWC 3.7 builds window.DWC before it loads any plugin script; DWC 3.6 has no window.DWC and loads the file as a webpack
  // chunk through self.webpackChunkduetwebcontrol. Both checks are exclusive in practice; DWC goes first.
  // Only a 3.7.x DWC runs the 3.7 bundle: a later line that keeps window.DWC (3.8) must not get code built for 3.7.
  if (host.DWC && typeof host.DWC === "object") {{
    if (/^3\.7(\.|$)/.test(String(host.DWC.version))) {{
      run37();
    }} else {{
      console.warn("[" + PLUGIN_ID + "] unsupported DWC version " + host.DWC.version + " (needs 3.7.x), plugin not started");
    }}
  }} else if (typeof self !== "undefined" && self.webpackChunkduetwebcontrol) {{
    run36();
  }} else {{
    console.warn("[" + PLUGIN_ID + "] unknown host (neither DWC 3.7 nor DWC 3.6), plugin not started");
  }}

  function run37() {{
    injectCss("3.7", CSS_37);
{js37}
  }}

  function run36() {{
    injectCss("3.6", CSS_36);
{js36}
  }}
}})();
"""


class MergeError(Exception):
    pass


def _empty_file_list(key, value):
    return key.endswith("Files") and value == []


def _entries(z):
    return {i.filename: z.read(i.filename) for i in z.infolist() if not i.filename.endswith("/")}


def _strip_map_comment(text):
    return re.sub(r"\n?//# sourceMappingURL=\S+\s*$", "", text)


def _split_dwc(files, label):
    """Returns (js_name, css_name_or_None, other_dwc_assets). .gz and .map companions are dropped (they describe the line files)."""
    js = [n for n in files if n.startswith("dwc/") and n.endswith(".js")]
    css = [n for n in files if n.startswith("dwc/") and n.endswith(".css")]
    if len(js) != 1:
        raise MergeError(f"{label}: expected exactly one dwc/**/*.js, found {len(js)}: {js}")
    if len(css) > 1:
        raise MergeError(f"{label}: more than one css file: {css}")
    skip = {js[0]} | set(css)
    assets = {n: d for n, d in files.items()
              if n.startswith("dwc/") and n not in skip and not n.endswith((".gz", ".map"))}
    return js[0], (css[0] if css else None), assets


def combine(zip36, zip37, out_path, allow_version_mismatch=False):
    """Merge the two line zips into out_path. Returns the manifest written."""
    with zipfile.ZipFile(zip36) as z:
        f36 = _entries(z)
    with zipfile.ZipFile(zip37) as z:
        f37 = _entries(z)
    for label, f in (("3.6 zip", f36), ("3.7 zip", f37)):
        if "plugin.json" not in f:
            raise MergeError(f"{label}: no plugin.json")
    m36 = json.loads(f36["plugin.json"].decode("utf-8"))
    m37 = json.loads(f37["plugin.json"].decode("utf-8"))

    # same plugin, same version, same manifest apart from the per-line keys
    for key in ("id", "version"):
        if m36.get(key) != m37.get(key):
            if key == "version" and allow_version_mismatch:
                continue
            raise MergeError(f"manifest {key} differs: 3.6 has {m36.get(key)!r}, 3.7 has {m37.get(key)!r}")
    # an empty list and a missing key mean the same (the 3.7 packager writes "dsfFiles": [], the 3.6 one omits it)
    rest36 = {k: v for k, v in m36.items() if k not in LINE_KEYS and not _empty_file_list(k, v)}
    rest37 = {k: v for k, v in m37.items() if k not in LINE_KEYS and not _empty_file_list(k, v)}
    if allow_version_mismatch:
        rest36.pop("version", None)
        rest37.pop("version", None)
    if rest36 != rest37:
        diff = sorted(k for k in set(rest36) | set(rest37) if rest36.get(k) != rest37.get(k))
        raise MergeError("manifests differ outside dwcVersion/dwcFiles/rrfFiles, keys: " + ", ".join(diff))
    for label, m in (("3.6", m36), ("3.7", m37)):
        if m.get("rrfFiles"):
            raise MergeError(f"{label} manifest lists rrfFiles {m['rrfFiles']}: not supported by the merge, check the 3.6 validator first")

    # sd/, dsf/ and everything that is not dwc/ or plugin.json must be identical
    payload36 = {n: d for n, d in f36.items() if not n.startswith("dwc/") and n != "plugin.json"}
    payload37 = {n: d for n, d in f37.items() if not n.startswith("dwc/") and n != "plugin.json"}
    if set(payload36) != set(payload37):
        raise MergeError("payload files differ: only in 3.6: " + str(sorted(set(payload36) - set(payload37)))
                         + "; only in 3.7: " + str(sorted(set(payload37) - set(payload36))))
    for n in sorted(payload36):
        if payload36[n] != payload37[n]:
            raise MergeError(f"payload file {n} differs between the 3.6 and the 3.7 zip")

    js36n, css36n, assets36 = _split_dwc(f36, "3.6 zip")
    js37n, css37n, assets37 = _split_dwc(f37, "3.7 zip")
    if set(assets36) != set(assets37) or any(assets36[n] != assets37[n] for n in assets36):
        raise MergeError("extra dwc/ assets differ between the two zips (only identical shared assets can be merged): "
                         + str(sorted(set(assets36) ^ set(assets37))))

    js36 = _strip_map_comment(f36[js36n].decode("utf-8"))
    js37 = _strip_map_comment(f37[js37n].decode("utf-8"))
    css36 = f36[css36n].decode("utf-8") if css36n else ""
    css37 = f37[css37n].decode("utf-8") if css37n else ""
    pid = m36["id"]
    # the 3.7 bundle must not be a webpack chunk and the 3.6 one must be: catches swapped inputs
    if "webpackChunkduetwebcontrol" not in js36:
        raise MergeError("the 3.6 zip's js is not a DWC 3.6 webpack chunk (inputs swapped?)")
    if "webpackChunkduetwebcontrol" in js37:
        raise MergeError("the 3.7 zip's js is a webpack chunk (inputs swapped?)")
    if 'DWC' not in js37:
        raise MergeError("the 3.7 zip's js never touches window.DWC (inputs swapped?)")

    def indent(code):
        return "\n".join(("    " + line if line else line) for line in code.split("\n"))

    combined = HEAD.format(
        id=pid, version=m36.get("version", ""), id_json=json.dumps(pid),
        css36=json.dumps(css36), css37=json.dumps(css37),
        js37=indent(js37), js36=indent(js36))
    digest = hashlib.sha256(combined.encode("utf-8")).hexdigest()[:8]
    js_rel = f"js/{pid}.{digest}.js"

    manifest = {k: v for k, v in m36.items() if not _empty_file_list(k, v)}
    manifest["dwcVersion"] = UNIVERSAL_DWC_VERSION
    manifest["dwcFiles"] = [js_rel]
    manifest.pop("rrfFiles", None)

    os.makedirs(os.path.dirname(os.path.abspath(out_path)), exist_ok=True)
    data = combined.encode("utf-8")
    with zipfile.ZipFile(out_path, "w", zipfile.ZIP_DEFLATED) as z:
        z.writestr("plugin.json", json.dumps(manifest, indent=2, ensure_ascii=False))
        z.writestr("dwc/" + js_rel, data)
        # DWC's own builds ship a precompressed copy next to the js; refresh it so it matches the merged file
        if any(n.endswith(".js.gz") for n in f36) or any(n.endswith(".js.gz") for n in f37):
            z.writestr("dwc/" + js_rel + ".gz", gzip.compress(data, 9, mtime=0))
        for n in sorted(assets36):
            z.writestr(n, assets36[n])
        for n in sorted(payload36):
            z.writestr(n, payload36[n])
    return manifest


def main():
    ap = argparse.ArgumentParser(description="Merge <Id>-dwc3.6.zip and <Id>-dwc3.7.zip into one universal zip")
    ap.add_argument("zip36")
    ap.add_argument("zip37")
    ap.add_argument("-o", "--out", required=True)
    ap.add_argument("--allow-version-mismatch", action="store_true", help="test only: accept different plugin versions in the two zips")
    a = ap.parse_args()
    try:
        m = combine(a.zip36, a.zip37, a.out, a.allow_version_mismatch)
    except MergeError as e:
        sys.exit("universal_zip: " + str(e))
    print(f"{m['id']} {m.get('version')}: universal zip {a.out} (dwcVersion {m['dwcVersion']}, {m['dwcFiles'][0]})")


if __name__ == "__main__":
    main()
